$statement = $pdo->prepare(
    "INSERT IGNORE INTO pages (title, slug, excerpt, body, status, published_at)
     VALUES (?, ?, ?, ?, 'published', NOW())"
);
foreach ($pages as [$title, $slug, $excerpt, $body]) {
    $statement->execute([$title, $slug, $excerpt, $body]);
}

$pageImages = [
    'our-journey' => 'assets/images/founder.jpeg',
    'fkf-board' => 'assets/images/board-rhoda.jpg',
    'health-education' => 'assets/images/cause-2a.jpg',
    'scholarships' => 'assets/images/cause-6a.jpg',
    'girlie-camp' => 'assets/images/camp1.jpg',
    'sexual-gender-based-violence' => 'assets/images/cause-1a.jpg',
];
$setPageImage = $pdo->prepare('UPDATE pages SET image_path = ? WHERE slug = ? AND image_path IS NULL');
foreach ($pageImages as $slug => $imagePath) {
    $setPageImage->execute([$imagePath, $slug]);
}

$gallery = [
    ['Francisca Kwamboka', 'Francisca Kwamboka', 'Francisca Kwamboka', 'assets/images/founder.jpeg'],
    ['Girlie Camp', 'Girlie Camp', 'Girlie Camp', 'assets/images/camp1.jpg'],
    ['Foundation community', 'Foundation community', 'Community work', 'assets/images/about.jpg'],
    ['Foundation programme', 'Foundation programme', 'Foundation programme', 'assets/images/slide-2a.jpg'],
    ['Foundation programme', 'Foundation programme', 'Foundation programme', 'assets/images/slide-sliders-2.jpg'],
