    ['Rhoda Onyancha', 'Chairperson', 'Rhoda Onyancha', 'assets/images/board-rhoda.jpg'],
    ["Martha Mang'are", 'Board Member', "Martha Mang'are", 'assets/images/board-mangare.jpg'],
    ['Alex Kalonzo', 'Board Secretary', 'Alex Kalonzo', 'assets/images/board-kalonzo.jpg'],
    ['Ivy Kwamboka', 'Board Member', 'Ivy Kwamboka', 'assets/images/board-ivy.jpg'],
