    ['Health & Education', 'Health & Education', 'Health & Education', 'assets/images/cause-2a.jpg'],
    ['Scholarships', 'Scholarships', 'Scholarships', 'assets/images/cause-6a.jpg'],
];
$findGallery = $pdo->prepare('SELECT id FROM gallery_items WHERE image_path = ? LIMIT 1');
$addGallery = $pdo->prepare(
    'INSERT INTO gallery_items (title, caption, alt_text, image_path, sort_order, is_published)
     VALUES (?, ?, ?, ?, ?, 1)'
);
foreach ($gallery as $index => [$title, $caption, $alt, $imagePath]) {
    $findGallery->execute([$imagePath]);
    if (!$findGallery->fetchColumn()) {
        $addGallery->execute([$title, $caption, $alt, $imagePath, $index]);
    }
}

$settings = [
    'site_name' => 'Francisca Kwamboka Foundation',
    'contact_email' => 'office@franciscakwambokafoundation.org',
    'contact_phone' => '+254 780971932',
    'postal_address' => 'P.O.Box 3952 - 40200, Kisii, Kenya',
    'office_locations' => 'Kisii, Nyamira and Machakos',
    'logo_path' => 'assets/images/fkf-logo.png',
];
$addSetting = $pdo->prepare('INSERT IGNORE INTO site_settings (setting_key, setting_value) VALUES (?, ?)');
foreach ($settings as $key => $value) {
